package dev.mote.collector

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.io.IOException
import java.nio.file.Files
import java.util.UUID
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.spec.GCMParameterSpec

/** Generated bytes only. Also runs on Android to exercise the same JSON/storage contracts. */
class CentralNativeContractTest {
    private fun encrypted() = object : ByteCipher {
        private val key = KeyGenerator.getInstance("AES").apply { init(128) }.generateKey()
        override fun seal(bytes: ByteArray): ByteArray = Cipher.getInstance("AES/GCM/NoPadding").run {
            init(Cipher.ENCRYPT_MODE, key); iv + doFinal(bytes)
        }
        override fun open(bytes: ByteArray): ByteArray = Cipher.getInstance("AES/GCM/NoPadding").run {
            init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, bytes.copyOfRange(0, 12))); doFinal(bytes.copyOfRange(12, bytes.size))
        }
    }
    private fun temporary(test: (File) -> Unit) {
        val root = Files.createTempDirectory("central-native-fixture").toFile()
        try { test(root) } finally { root.deleteRecursively() }
    }
    private val origin = "https://central.fixture.invalid"
    private val token = "generated-native-owner-fixture-token-123456"

    @Test fun allFeaturesUseTheSameConfiguredLoginIncludingPairedTokens() {
        val config = CollectorConfig(server = origin, token = token, deviceName = "Generated phone")
        assertEquals(token, config.connectionToken()); assertTrue(config.hasSyncConnection())
    }
    @Test fun signedOutAndExpiredLoginsCannotResumeCollectionOrCentralRequests() {
        val config = CollectorConfig(server = origin, token = token, deviceName = "Generated phone")
        for (closed in listOf(config.copy(authSignedOut = true), config.copy(authExpiresAt = 1))) {
            assertEquals("", closed.connectionToken()); assertFalse(closed.hasSyncConnection())
        }
        assertEquals(token, config.copy(authExpiresAt = System.currentTimeMillis() + 86400000).connectionToken())
    }
    @Test fun appOnlyLoginCannotRestoreAfterProcessRestart() {
        val config = CollectorConfig(server = origin, token = token, deviceName = "Generated phone")
        assertEquals(token, config.copy(authProcess = LoginProcess.id).connectionToken())
        assertEquals("", config.copy(authProcess = "generated-previous-process").connectionToken())
    }
    @Test fun transportOnlyUsesFixedApiOriginAndRedactsCredential() {
        val calls = mutableListOf<String>()
        val client = CentralClient(origin, token, { _, url, _, auth, _ ->
            assertEquals(token, auth); calls.add(url); 200 to JSONObject().put("ok", true)
        })
        client.get("/api/status"); assertEquals(listOf("$origin/api/status"), calls)
        for (path in listOf("https://other.invalid/api/status", "//other.invalid/api/status", "/oauth/callback", "/api/../status", "/api/%2e%2e/status", "/api/status#token"))
            assertThrows(IllegalArgumentException::class.java) { client.get(path) }
        assertEquals(1, calls.size); assertFalse(client.toString().contains(token))
    }
    @Test fun unauthorizedIsDifferentFromAConnectorNeedingAuthorization() {
        var invalidations = 0
        val unauthorized = CentralClient(origin, token, { _, _, _, _, _ -> 401 to JSONObject().put("error", "unauthorized") }, unauthorized = { invalidations++ })
        val failure = assertThrows(CentralFailure::class.java) { unauthorized.get("/api/status") }; assertEquals("unauthorized", failure.code)
        assertEquals(1, invalidations)
        val connector = CentralClient(origin, token, { _, _, _, _, _ -> 401 to JSONObject().put("error", "google_not_connected").put("message", "Generated connector status") }, unauthorized = { invalidations++ })
        val separate = assertThrows(CentralFailure::class.java) { connector.get("/api/connectors/google/calendars") }
        assertEquals("google_not_connected", separate.code); assertTrue(separate.message!!.contains("Google")); assertFalse(separate.message!!.contains("Generated connector status"))
        assertEquals(1, invalidations)
    }
    @Test fun backgroundTransportPreservesNodeLoginWhenExternalAuthorizationFails() {
        val previous = HttpJson.onUnauthorized; var invalidations = 0
        HttpJson.onUnauthorized = { url, credential -> assertEquals("$origin/api/status", url); assertEquals(token, credential); invalidations++ }
        try {
            HttpJson.rejectUnauthorized(401, "$origin/api/status", token, "google_not_connected")
            HttpJson.rejectUnauthorized(403, "$origin/api/status", token, "unauthorized")
            assertEquals(0, invalidations)
            for (error in listOf("unauthorized", "connection_revoked", "")) HttpJson.rejectUnauthorized(401, "$origin/api/status", token, error)
            assertEquals(3, invalidations)
            HttpJson.rejectUnauthorized(401, "$origin/api/status", "", "unauthorized")
            assertEquals(3, invalidations)
        } finally { HttpJson.onUnauthorized = previous }
    }
    @Test fun noteOutboxSurvivesAmbiguousAckAndOnlyRemovesTheExactReceipt() = temporary { root ->
        val cipher = encrypted(); val store = CentralNoteStore(root, cipher)
        val text = "Generated 中文 🐾 <script>untrusted evidence</script>"
        store.edit(text, "fixture", JSONArray()); val note = store.enqueue("fixture-phone", "Generated phone")
        assertEquals("", store.read().getJSONObject("draft").getString("text"))
        assertThrows(IllegalArgumentException::class.java) { store.enqueue("fixture-phone", "Generated phone") }
        val restored = CentralNoteStore(root, cipher)
        assertEquals(note.toString(), restored.read().getJSONArray("pending").getJSONObject(0).toString())
        assertFalse(String(File(root, "notes.enc").readBytes()).contains("untrusted evidence"))
        assertThrows(IllegalArgumentException::class.java) { restored.acknowledge(note.getString("id"), JSONObject().put("id", UUID.randomUUID().toString())) }
        assertEquals(1, restored.read().getJSONArray("pending").length())
        val receipt = JSONObject().put("version", 2).put("id", note.getString("id")).put("kind", "capture").put("state", "received").put("duplicate", false)
        restored.acknowledge(note.getString("id"), JSONObject().put("id", note.getString("id")).put("duplicate", false).put("receipt", receipt))
        assertEquals(0, restored.read().getJSONArray("pending").length())
    }
    private fun fileReplayAck(manifest: JSONObject, id: String): JSONObject {
        val item = manifest.getJSONObject("item")
        val identity = JSONObject().put("id", id).put("sourceId", manifest.getString("sourceId"))
            .put("externalId", item.getString("externalId")).put("revision", item.getString("revision")).put("duplicate", true)
        val receipt = JSONObject(identity.toString()).put("version", 2).put("kind", "file-revision").put("state", "received")
        val hash = manifest.getString("sha256")
        return identity.put("captureId", id).put("objectId", hash).put("sha256", hash)
            .put("sizeBytes", manifest.getLong("sizeBytes")).put("receipt", receipt)
    }
    private fun partAck(part: Int, bytes: ByteArray) = JSONObject().put("part",part).put("bytes",bytes.size).put("hash",java.security.MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) })
    @Test fun attachmentRetryPreservesManifestAndSkipsDurableParts() = temporary { root ->
        val partBytes = 4 * 1024 * 1024
        val original = ByteArray(partBytes + 3) { (it % 251).toByte() }
        val file = File(root, "generated-image").apply { writeBytes(original) }
        val uploadId = UUID.randomUUID().toString()
        val captureId = UUID.randomUUID().toString()
        val uploads = "/api/file-sync/v1/uploads"
        val manifests = mutableListOf<String>()
        val parts = mutableListOf<Int>()
        val durable = JSONArray()
        var commits = 0
        val client = CentralClient(origin, token, { method, url, bytes, _, _ ->
            when (method to url.removePrefix(origin)) {
                "POST" to "/api/sources" -> 200 to JSONObject()
                "POST" to uploads -> {
                    manifests += String(requireNotNull(bytes), Charsets.UTF_8)
                    val begin = JSONObject().put("partBytes", partBytes)
                    if (commits == 0) {
                        begin.put("uploadId", uploadId).put("parts", JSONArray(durable.toString()))
                            .put("nextPart", JSONObject.NULL).put("ack", JSONObject.NULL)
                    } else {
                        begin.put("uploadId", captureId).put("parts", JSONArray()).put("ack", fileReplayAck(JSONObject(manifests.first()), captureId))
                    }
                    200 to begin
                }
                "PUT" to "$uploads/$uploadId/parts/0", "PUT" to "$uploads/$uploadId/parts/1" -> {
                    val part = url.substringAfterLast('/').toInt()
                    val body = requireNotNull(bytes)
                    parts += part
                    assertArrayEquals(original.copyOfRange(part * partBytes, minOf((part + 1) * partBytes, original.size)), body)
                    if (part == 1 && manifests.size == 1) {
                        throw IOException("Generated lost request before the tail was stored")
                    }
                    val ack = partAck(part, body)
                    durable.put(part, ack)
                    200 to ack
                }
                "POST" to "$uploads/$uploadId/commit" -> {
                    assertEquals(2, durable.length())
                    commits++
                    throw IOException("Generated lost response after the revision was committed")
                }
                else -> error("Unexpected attachment request: $method $url")
            }
        })
        fun upload() = CentralAttachments.upload(client, file, "fixture.png", "image/png", "fixture-phone", { 1000L })
        assertThrows(IOException::class.java) { upload() }
        assertThrows(IOException::class.java) { upload() }
        assertEquals(captureId, upload())
        assertEquals(List(3) { manifests.first() }, manifests)
        assertEquals(listOf(0, 1, 1), parts)
        assertEquals(1, commits)
    }
    @Test fun importRetryAfterLostAdmissionResponseUsesSameArchivedFileAndRequestId() = temporary { root ->
        val cipher = encrypted()
        val uploadId = UUID.randomUUID().toString()
        val requestId = UUID.randomUUID().toString()
        val fileId = UUID.randomUUID().toString()
        val jobId = UUID.randomUUID().toString()
        val original = byteArrayOf(1, 2, 3)
        val manifest = JSONObject().put("id", uploadId).put("name", "generated.txt").put("sizeBytes", original.size)
        CentralStateFile(root, "import", cipher).write(JSONObject().put("manifest", manifest)
            .put("requestId", requestId).put("instruction", "Generated instruction"))
        val part = File(root, "part-0.enc").apply { writeBytes(cipher.seal(original)) }
        val uploads = "/api/import-uploads"
        var commits = 0
        var partCalls = 0
        val requests = mutableListOf<String>()
        val client = CentralClient(origin, token, { method, url, bytes, _, _ ->
            when (method to url.removePrefix(origin)) {
                "POST" to uploads -> {
                    assertEquals(manifest.toString(), String(requireNotNull(bytes), Charsets.UTF_8))
                    200 to JSONObject().put("id", uploadId).put("partBytes", 4 * 1024 * 1024).put("parts", JSONArray())
                        .put("nextPart", JSONObject.NULL).apply { if (commits > 0) put("fileId", fileId) }
                }
                "PUT" to "$uploads/$uploadId/parts/0" -> {
                    val body = requireNotNull(bytes)
                    assertArrayEquals(original, body)
                    partCalls++
                    200 to partAck(0, body)
                }
                "POST" to "$uploads/$uploadId/commit" -> {
                    assertEquals(1, partCalls)
                    commits++
                    200 to JSONObject().put("id", fileId)
                }
                "POST" to "/api/imports" -> {
                    requests += String(requireNotNull(bytes), Charsets.UTF_8)
                    if (requests.size == 1) throw IOException("Generated lost admission response")
                    202 to JSONObject().put("id", jobId)
                }
                else -> error("Unexpected import request: $method $url")
            }
        })
        val store = CentralImports(root, cipher)
        assertThrows(IOException::class.java) { store.send(client) { _, _ -> } }
        val restored = CentralImports(root, cipher)
        val pending = restored.pending()
        assertEquals(manifest.toString(), pending.getJSONObject("manifest").toString())
        assertEquals(fileId, pending.getString("archivedFileId"))
        assertArrayEquals(original, cipher.open(part.readBytes()))
        assertEquals(jobId, restored.send(client) { _, _ -> }.getString("id"))
        assertEquals(2, requests.size)
        assertEquals(requests[0], requests[1])
        assertEquals(1, partCalls)
        assertEquals(2, commits)
        assertFalse(restored.pending().has("manifest"))
        assertFalse(part.exists())
        val admitted = JSONObject(requests.first())
        assertEquals(requestId, admitted.getString("requestId"))
        assertEquals(fileId, admitted.getJSONArray("archivedFileIds").getString(0))
    }
}
